namespace ghidra.feature.fid.db;








using generic.jar;
using generic.util;
using ghidra.framework;
using ghidra.framework.preferences;
using ghidra.util;
using ghidra.util.datastruct;
using ghidra.util.datastruct;
using ghidra.util.exception;
using ghidra.util.exception;
using ghidra.util.task;
using ghidra.util.task;

/**
 * Manages the set of FidFiles for the application. This uses the singleton pattern and
 * all users of Fid databases must use this to get open Fid databases.  This ensures that
 * there is only one updatable Fid database open for any given FidFile.
 */
public class FidFileManager {

	private static readonly string SEPARATOR = ";";
	private static readonly string INACTIVE_FID_FILES = "FID.INACTIVE";
	private static readonly string USER_ADDED_FILES = "FID.USER.ADDED";

	private static FidFileManager THE_FID_FILE_MANAGER;

	private Set<FidFile> fidFiles;
	private WeakSet<ChangeListener> listeners;

	/**
	 * {@return the singleton instance of the FidFileManager.}
	 */
	public static FidFileManager getInstance() {
		if (THE_FID_FILE_MANAGER == null) {
			THE_FID_FILE_MANAGER = new FidFileManager();
		}
		return THE_FID_FILE_MANAGER;
	}

	private FidFileManager() {
		listeners = WeakDataStructureFactory.createCopyOnWriteWeakSet();
	}

	private Set<FidFile> loadFidFiles() {
		if (fidFiles == null) {

			TaskLauncher.launchModal("Loading Fid Files", monitor => {

				fidFiles = new();
				try {
					findDeliveredFidFiles(monitor);
					restoreFromPreferences(monitor);
				}
				catch (CancelledException ce) {
					Msg.showWarn(this, null, "Fid Loading Cancelled", "User cancelled Fid Db " +
						"loading.  To load all Fid Db files, the tool must be restarted.");
				}
			});
		}

		return fidFiles;
	}

	/**
	 * Add user FidDb file
	 * @param file the file
	 * @return FidFile or null if invalid
	 */
	public FidFile addUserFidFile(File file) {
		loadFidFiles();
		FidFile fidFile = findExistingFidFile(file);
		if (fidFile != null) {
			return fidFile;
		}

		fidFile = new FidFile(this, file, false);
		if (fidFile.isValidFile()) {
			fidFiles.add(fidFile);
			saveToPreferences();
			notifyListeners();
			return fidFile;
		}
		return null;
	}

	private FidFile findExistingFidFile(File file) {
		loadFidFiles();
		foreach (FidFile fidFile in fidFiles) {
			if (fidFile.getFile().equals(file)) {
				return fidFile;
			}
		}
		return null;
	}

	/**
	 * {@return a list of all the FidFiles know to the application.}
	 */
	public List<FidFile> getFidFiles() {
		loadFidFiles();
		List<FidFile> files = new(fidFiles);
		Collections.sort(files);
		return files;
	}

	/**
	 * Triggers a load of the Fid db files, if not already loaded.
	 */
	public void load() {
		if (fidFiles == null) {
			loadFidFiles();
		}
	}

	/**
	 * {@return true if Fid db files have been loaded and files have been found.}
	 */
	public bool hasFidFiles() {
		return fidFiles != null && !fidFiles.isEmpty();
	}

	/**
	 * {@return true if Fid db files have been loaded and user Fid files have been found.}
	 */
	public bool hasUserFidFiles() {
		if (fidFiles == null) {
			return false;
		}

		foreach (FidFile fidFile in fidFiles) {
			if (!fidFile.isInstalled()) {
				return true;
			}
		}
		return false;
	}

	/**
	 * {@return true if the Fid db files have been loaded.}
	 */
	public bool hasLoadedFidFiles() {
		return fidFiles != null;
	}

	/**
	 * {@return a list of all the user added (non installation) Fid files.  This will
	 * be files containing packed databases.}
	 */
	public List<FidFile> getUserAddedFiles() {
		loadFidFiles();
		List<FidFile> files = new();
		foreach (FidFile fidFile in fidFiles) {
			if (!fidFile.isInstalled()) {
				files.add(fidFile);
			}
		}
		Collections.sort(files);
		return files;
	}

	/**
	 * Opens all the Fid Databases applicable for the given Language and CompilerSpec,
	 * and returns a FidQueryService as a convenience for querying multiple FID files
	 * at the same time.  The CompilerSpec can be null to indicate the service should not
	 * filter out results whose compiler spec doesn't match.
	 * 
	 * @param programID the properties of the program to be queried
	 * @param openForUpdate if true, all non-installation databases will be open for update;
	 * otherwise they will be read-only.
	 * @return a FidQueryService which is a convenience for querying multiple databases at the same time.
	 * @throws VersionException if any of the fidFiles have a database Schema that is not the current version.
	 * @throws IOException if a general I/O error occurs.
	 */
	public FidQueryService openFidQueryService(FidProgramID programID, bool openForUpdate)
    {
		loadFidFiles();
		return new FidQueryService(fidFiles, programID, openForUpdate);
	}

	/**
	 * Creates a new FidDatabse and FidFile.
	 * @param dbFile the file to where the fidDatabase should be created.  It must not exist.
	 * @throws IOException If the new FidFile database could not be created.
	 */
	public void createNewFidDatabase(File dbFile)
    {
		FidDB.createNewFidDatabase(dbFile);
		FidFile newFidFile = new FidFile(this, dbFile, false);
		loadFidFiles();
		fidFiles.add(newFidFile);
		saveToPreferences();
		notifyListeners();
	}

	/**
	 * Removes the given FidFile from the application.  Note: this does not delete the file,
	 * it only removes it from the applications list of knows FidFiles.
	 * @param fidFile the fidFile to remove.
	 */
	public void removeUserFile(FidFile fidFile) {
		loadFidFiles();
		fidFiles.remove(fidFile);
		saveToPreferences();
		notifyListeners();
	}

	/**
	 * Returns true if any FidFile database known to the application can support
	 * the given language and compiler.
	 * @param programID the properties of the program we want to query against
	 * @return true if any known FidFile database can support the given language and compiler.
	 */
	public bool canQuery(FidProgramID programID) {
		loadFidFiles();
		foreach (FidFile file in fidFiles) {
			if (file.isActive() && file.canProcess(programID)) {
				return true;
			}
		}
		return false;
	}

	/**
	 * Adds a listener to be notified when the list of FidFiles change. NOTE: this object
	 * uses a weak set, so you can't pass anonymous listeners or they will be immediately
	 * garbage collected.
	 * @param listener the listener to be notified.
	 */
	public void addChangeListener(ChangeListener listener) {
		listeners.add(listener);
	}

	/**
	 * Removes a listener to be notified when the list of FidFiles change.
	 * @param listener the listener to no longer be notified.
	 */
	public void removeChangeListener(ChangeListener listener) {
		listeners.remove(listener);
	}

	private void saveToPreferences() {
		List<FidFile> userAddedFiles = getUserAddedFiles();
		saveFilesToPreferences(USER_ADDED_FILES, userAddedFiles);

		List<FidFile> inactiveFiles = getInactiveFiles();
		saveFilesToPreferences(INACTIVE_FID_FILES, inactiveFiles);
	}

	private void saveFilesToPreferences(string preferenceName, List<FidFile> files) {
		StringBuilder builder = new StringBuilder();
		foreach (FidFile file in files) {
			if (builder.length() > 0) {
				builder.append(SEPARATOR);
			}
			Path path = new Path(file.getFile());
			builder.append(path.getPathAsString());
		}
		Preferences.setProperty(preferenceName, builder.toString());
	}

	private List<FidFile> getInactiveFiles() {
		loadFidFiles();
		List<FidFile> list = new();
		foreach (FidFile fidFile in fidFiles) {
			if (!fidFile.isActive()) {
				list.add(fidFile);
			}
		}
		return list;
	}

	private void restoreFromPreferences(TaskMonitor monitor)
    {
		Set<File> userAddedFiles = getFilesFromPreference(USER_ADDED_FILES);
		monitor.initialize(userAddedFiles.size(), "Adding user Fid files...");
		doAddUserFidFiles(userAddedFiles, monitor);

		Set<File> excludedFiles = getFilesFromPreference(INACTIVE_FID_FILES);
		monitor.initialize(excludedFiles.size(), "Removing inactive user Fid files...");
		doExcludeFidFiles(excludedFiles, monitor);
	}

	private void doAddUserFidFiles(Set<File> userAddedFiles, TaskMonitor monitor)
    {
		foreach (File file in userAddedFiles) {
			monitor.increment();
			FidFile fidFile = new FidFile(this, file, false);
			if (fidFile.isValidFile()) {
				fidFiles.add(fidFile);
			}
		}
	}

	private void doExcludeFidFiles(Set<File> excludedFiles, TaskMonitor monitor)
    {
		foreach (FidFile fidFile in fidFiles) {
			monitor.increment();
			if (excludedFiles.contains(fidFile.getFile())) {
				fidFile.setActive(false);
			}
		}
	}

	private Set<File> getFilesFromPreference(string preferenceName) {
		Set<File> set = new();
		string concatenatedFilePaths = Preferences.getProperty(preferenceName, "", true);
		string[] filePaths = concatenatedFilePaths.split(SEPARATOR);
		foreach (string filePath in filePaths) {
			filePath = filePath.trim();
			if (filePath.length() == 0) {
				continue;
			}
			Path path = new Path(filePath);
			ResourceFile resourceFile = path.getPath();
			if (resourceFile.exists()) {
				set.add(resourceFile.getFile(false));
			}
		}
		return set;
	}

	private void findDeliveredFidFiles(TaskMonitor monitor)
    {

		List<ResourceFile> foundFiles =
			Application.findFilesByExtensionInApplication(FidFile.FID_RAW_DATABASE_FILE_EXTENSION);

		monitor.initialize(foundFiles.size(), "Processing included Fid files...");
		foreach (ResourceFile resourceFile in foundFiles) {
			monitor.increment();
			File file = resourceFile.getFile(true);
			FidFile fidFile = new FidFile(this, file, true);
			if (fidFile.isValidFile()) {
				fidFiles.add(fidFile);
			}
		}
	}

	void activeStateChanged(FidFile fidFile) {
		saveFilesToPreferences(INACTIVE_FID_FILES, getInactiveFiles());
	}

	private void notifyListeners() {
		foreach (ChangeListener listener in listeners) {
			listener.stateChanged(null);
		}
	}
}
